// Native 0x1426b2e20. Applies to every AFortWeapon in the world owned by this weapon's owning player controller.
bool bResult = false;
AFortPlayerController* OwnerController = Cast<AFortPlayerController>(GetOwner());
if (!OwnerController)
{
    return bResult;
}
for (AFortWeapon* Weapon : GetAllWeaponActors(GetWorld()))
{
    if (Weapon->HasWeaponStats() && Weapon->GetOwningController() == OwnerController)
    {
        bResult = SetSceneComponentHiddenInGameInternal(Weapon, SceneComp, bPropagateToChildren, bHidden);
    }
}
return bResult;
